function Empty({icon:Icon=BikeIcon,title,children,action}:{icon?:typeof BikeIcon;title:string;children:ReactNode;action?:ReactNode}){return <div className="empty"><div className="empty-icon"><Icon size={27}/></div><h3>{title}</h3><p>{children}</p>{action}</div>}
/** While BAK is still writing, a table arrives a row at a time: hold it back until its last row is in, so raw "| a | b |" lines never flash. */
const liveText=(t:string)=>{const lines=t.split('\n');let end=lines.length;while(end>0&&/^\s*\|/.test(lines[end-1]))end--;return end<lines.length?lines.slice(0,end).join('\n'):t;};
